// Independent oracle: min-cost flow on a forward time network, no reward search.
#include <bits/stdc++.h>
using namespace std;using ll=long long;struct Edge{int to,back,capacity;ll cost;};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;ll budget;cin>>n>>budget;vector<ll>a(n),b(n);for(ll&x:a)cin>>x;for(ll&x:b)cin>>x;int S=n,T=n+1,V=n+2;vector<vector<Edge>>g(V);auto edge=[&](int u,int v,int cap,ll cost){g[u].push_back({v,int(g[v].size()),cap,cost});g[v].push_back({u,int(g[u].size())-1,0,-cost});};for(int i=0;i<n;++i){edge(S,i,1,a[i]);edge(i,T,1,b[i]);if(i+1<n)edge(i,i+1,n,0);}const ll INF=LLONG_MAX/4;vector<ll>potential(V),distance(V);vector<int>from(V),which(V);ll total=0;int answer=0;for(;;){fill(distance.begin(),distance.end(),INF);distance[S]=0;priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>>pq;pq.emplace(0,S);while(!pq.empty()){auto [d,u]=pq.top();pq.pop();if(d!=distance[u])continue;for(int i=0;i<int(g[u].size());++i){auto &e=g[u][i];ll nd=d+e.cost+potential[u]-potential[e.to];if(e.capacity&&nd<distance[e.to]){distance[e.to]=nd;from[e.to]=u;which[e.to]=i;pq.emplace(nd,e.to);}}}if(distance[T]==INF)break;ll marginal=distance[T]+potential[T]-potential[S];if(total+marginal>budget)break;for(int v=0;v<V;++v)if(distance[v]!=INF)potential[v]+=distance[v];total+=marginal;++answer;for(int v=T;v!=S;v=from[v]){auto &e=g[from[v]][which[v]];--e.capacity;++g[v][e.back].capacity;}}cout<<answer<<'\n';}
